"""Every vector generated by the JavaScript adapter must come out identical here: records, routes, receipts,
action findings, digests and error messages. Comparison is by canonical JSON, so number formatting counts."""
import base64
import json
from pathlib import Path

import pytest

import curbi_decisions as D

VECTORS = json.loads((Path(__file__).parent / "vectors.json").read_text(encoding="utf-8"))["vectors"]


def run(v):
    try:
        if v["kind"] == "normalize":
            a = dict(v["args"])
            fn = D.normalize_systemone if v["shape"] == "systemone" else D.normalize_decisions
            kw = {"provider": a["provider"], "received_at": a.get("received_at")}
            for k in ("request", "response"):
                if k in a:
                    kw[k] = a[k]
            if "request_bytes_utf8" in a:
                kw["request_bytes"] = a["request_bytes_utf8"].encode("utf-8")
            for k in ("request", "response"):
                if f"{k}_bytes_b64" in a:
                    kw[f"{k}_bytes"] = base64.b64decode(a[f"{k}_bytes_b64"])
            return {"ok": True, "records": fn(**kw)}
        if v["kind"] == "policy":
            return {"ok": True, "compiled": D.compile_decision_policy(v["policy"])}
        pol = D.compile_decision_policy(v["policy"])
        result = D.route(pol, "q", v["records"], now=v["now"])
        i = int(v["name"].split(":")[1])
        receipt = D.decision_receipt(policy=pol, question_id="q", records=v["records"], result=result, prev="sha256:prev" if i % 2 else None)
        return {"ok": True, "result": result, "receipt": receipt, "actions": {op: D.check_action(pol, "q", result, op) for op in ["billing.refund", "other.op"]}}
    except (D.Malformed, D.PolicyError) as e:
        return {"ok": False, "error": str(e)}


def expected(v):
    keys = {"normalize": ["records"], "policy": ["compiled"], "route": ["result", "receipt", "actions"]}[v["kind"]]
    return {"ok": True, **{k: v[k] for k in keys}} if v["ok"] else {"ok": False, "error": v["error"]}


@pytest.mark.parametrize("v", VECTORS, ids=[f"{v['kind']}:{v['name']}" for v in VECTORS])
def test_matches_javascript(v):
    assert D.canonical(run(v)) == D.canonical(expected(v))


def test_vector_set_is_broad():
    kinds = {(v["kind"], v["ok"]) for v in VECTORS}
    assert kinds == {("normalize", True), ("normalize", False), ("policy", True), ("policy", False), ("route", True)}
    assert len(VECTORS) > 1500
    assert {r["result"]["outcome"] for r in VECTORS if r["kind"] == "route"} >= {"act", "hand_off", "deny", "escalate"}
